import type { NextConfig } from 'next';

const nextConfig: NextConfig = {
  experimental: {
    // Automatically transforms barrel imports for supported UI/utility libraries
    optimizePackageImports: [
      'lucide-react',
      'date-fns',
      'lodash-es',
      '@radix-ui/react-icons'
    ],
  },
  webpack: (config, { isServer }) => {
    if (!isServer) {
      // Eliminate unnecessary locale payload chunks from vendor packages
      config.resolve.alias = {
        ...config.resolve.alias,
        './locale': false,
      };
    }
    return config;
  },
};

export default nextConfig;

'use client';

import React, { useState } from 'react';
import dynamic from 'next/dynamic';

// Heavy calculator with mathematical matrix libraries and charting
const DynamicValuationCalculator = dynamic(
  () => import('@/components/features/valuation/valuation-calculator'),
  {
    ssr: false,
    loading: () => (
      <div className="h-96 w-full animate-pulse rounded-2xl bg-neutral-900/40 p-8 flex items-center justify-center">
        <p className="text-neutral-400 font-mono text-sm tracking-wide">Loading Valuation Engine...</p>
      </div>
    ),
  }
);

export function PropertyValuationSection({ propertyId }: { propertyId: string }) {
  const [isActivated, setIsActivated] = useState(false);

  return (
    <section className="relative my-16 border-t border-neutral-800 pt-12">
      <div className="flex flex-col md:flex-row md:items-center justify-between mb-8 gap-4">
        <div>
          <h3 className="text-2xl font-semibold text-white">Instant Asset Valuation</h3>
          <p className="text-neutral-400 text-sm mt-1">Algorithmic projection based on historical Mayfair & Monaco transaction comps.</p>
        </div>
        {!isActivated && (
          <button
            onClick={() => setIsActivated(true)}
            className="px-6 py-3 rounded-lg bg-emerald-500 hover:bg-emerald-400 text-black font-semibold text-sm transition-colors"
          >
            Initialize Engine
          </button>
        )}
      </div>

      {isActivated ? (
        <DynamicValuationCalculator propertyId={propertyId} />
      ) : (
        <div className="h-48 rounded-xl border border-dashed border-neutral-800 flex items-center justify-center">
          <p className="text-xs text-neutral-500 uppercase tracking-widest font-mono">
            Click initialize to stream valuation model (~42KB chunk)
          </p>
        </div>
      )}
    </section>
  );
}
